return $input.all().map((item) => {
  const alert = item.json && item.json.alert;
  if (!alert || typeof alert !== 'object' || !alert.alert_id) {
    throw new Error('Resolved Alert row did not contain a Standard Alert');
  }
  const location = alert.location && typeof alert.location === 'object' ? alert.location : {};
  if (!Number.isFinite(Number(location.latitude)) || !Number.isFinite(Number(location.longitude))) {
    throw new Error('Resolved Alert did not contain coordinates');
  }
  return { json: { ...alert, location } };
});

